      "@docs:openapi:lint"
    ],
    "qa": [
      "@qa:static"
    ],
    "test:integration": "php scripts/run-billing-test-suite.php integration",
    "test:e2e:ux": "php scripts/run-billing-test-suite.php e2e:ux",
    "test:e2e": "php scripts/run-billing-test-suite.php e2e",
    "test:package-smoke": "php vendor/bin/phpunit tests/Contract/Billing/BillingPackageSmokeTest.php"
  },
